<?php
namespace SenderSuite;

/** Dispatched only inside DataRoutes' own-app authentication/origin/transaction guard. */
final class VariableRoutes {
    public static function definitions(){return array_merge(ContactProfile::definitions(),array('/variables/?'=>array('GET','POST'),'/variables/sync'=>array('POST'),'/variables/preview'=>array('POST'),'/variables/(?P<variable_id>-?[0-9]+)'=>array('PUT','DELETE')));}
    public static function handle($request,array $context,&$status){$path=trim(substr($request->get_route(),strlen('/sender-suite/v1/')),'/');$method=$request->get_method();$q=$request->get_query_params();$service=new Variables($context['db']);if(preg_match('#^variables/contact/(-?[0-9]+)/profile$#D',$path,$m)&&$method==='GET'){return (new ContactProfile($context['db']))->read(DataRoutes::integer($m[1],'contact_id'));}if($path==='variables'){if($method==='GET'){$sync=array_key_exists('sync',$q)?DataRoutes::boolean($q['sync'],'sync'):true;return $service->listing(DataRoutes::text($q,'search'),DataRoutes::text($q,'source'),$sync);}if($method==='POST'){$status=201;return $service->create(DataRoutes::body($request));}}if($path==='variables/sync'&&$method==='POST'){return $service->sync();}if($path==='variables/preview'&&$method==='POST'){if(!array_key_exists('body',$q)){throw new ValidationFailure('Field required','body');}$body=DataRoutes::text($q,'body',null,1);$contact=null;if(isset($q['contact_id'])){$id=DataRoutes::integer($q['contact_id'],'contact_id');if($id!==0){$contact=(new Contacts($context['db']))->find($id);}}return $service->analyze($body,$contact);}if(preg_match('#^variables/(-?[0-9]+)$#D',$path,$m)){$id=DataRoutes::integer($m[1],'variable_id');if($method==='PUT'){return $service->update($id,DataRoutes::body($request));}if($method==='DELETE'){$service->delete($id);$status=204;return null;}}throw new AuthFailure(404,'Not Found');}
}
